mapper.select:
SELECT approve_status AS tabFlag, count(*) AS count FROM so_receipt WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status

select si.id as soId, si.code as soCode, si.sales_org_id as salesOrgId, si.approve_status as approveStatus, si.receive_account as receiptAccount, si.receive_amount - COALESCE(( select sum(red.receipt_amount) from so_receipt re inner join so_receipt_detail red on re.id = red.main_id where re.is_deleted = false and red.is_deleted = false and re.approve_status = 'approved' and red.so_id = si.id ),0) as remainReceiptAmount from so_info si where si.is_deleted = false and si.invalid_status = false and si.customer_id = #{params.customerId}
and si.code ILIKE concat('%',#{params.soCode}::text,'%')
AND si.code IN
#{item}

select srd.so_code, srd.so_id, sum(srd.receipt_amount) as receiptAmount from so_receipt sr inner join so_receipt_detail srd on sr.id = srd.main_id and srd.is_deleted = false where sr.is_deleted = false and sr.approve_status = 'approved' and srd.so_id in
#{soId}
group by srd.so_code,srd.so_id
